class Stack:
 def __init__(self,v): self.v=list(v)
 def isEmpty(self): return not self.v
 def pop(self): return self.v.pop()
 def push(self,x): self.v.append(x)
class Queue:
 def __init__(self): self.v=[]
 def isEmpty(self): return not self.v
 def enqueue(self,x): self.v.append(x)
 def dequeue(self): return self.v.pop(0)
s=Stack(["A","B","C"]);q=Queue();reverse_using_queue(s,q)
assert s.v==["C","B","A"] and q.isEmpty()
