def smallest_row_total(grid):
    best=None
    indices=[]
    for r in range(len(grid)):
        total=0
        for value in grid[r]:
            total+=value
        if best is None or total < best:
            best=total
            indices=[r]
        elif total == best:
            indices.append(r)
    return best,indices

